SCRIPT_DIR=$(mktemp -d /tmp/card-3409-writer.XXXXXX) && cat > "$SCRIPT_DIR/write_card.py" <<'PYEOF'
import collections
import json
import os
import re
import sys

OUT = os.path.abspath(sys.argv[1])
with open(os.path.join(OUT, "facts.json"), encoding="utf-8") as fh:
    FACTS = json.load(fh)
MAIN = FACTS["branches"]["main"]
NATIVE = FACTS["branches"]["native-v1"]
KNOWN = FACTS["known_main_failures"]

MAIN_PR = "https://github.com/Abdullah1738/CrpkoArchitectureBroker/pull/300"
NATIVE_PR = "https://github.com/Abdullah1738/CrpkoArchitectureBroker/pull/301"
CARD_LINK = "t3-context://v1/kanban-card/card-d928b9b0-9893-410b-8b9f-eaf4aa064b5f"
MAIN_TITLE = "fix(openapi): correct primitive types and nullable asset metadata"
NATIVE_TITLE = "fix(openapi-native): correct primitive types and nullable asset metadata"
SCOPE = ("Generator and tests only. No contracts, frontend code, workflows, or compiled "
         "artifacts are tracked, and no release or deploy is triggered.")
CI_LINES = [
    "## CI and deploy",
    "",
    "- No PR CI exists for this repository. The only tracked workflow is deploy.yml, "
    "which runs on workflow_dispatch only.",
    "- The deploy workflow was not triggered for this change. No workflows were run, "
    "dispatched, or re-run.",
    "- Hosted CI cannot report green under the current scope. The recorded test and "
    "artifact evidence in this description is the verification record.",
]
TITLE_RE = re.compile(r"^(feat|fix|docs|refactor|test|chore|build|ci|perf|style)"
                      r"(\([a-z0-9][a-z0-9-]*\))?!?: \S.*$")
BANNED = [re.compile(w, re.I) for w in ("round", "astra", "finding", "review")]
MARKERS = [re.compile(p, f) for p, f in [
    (r"\bAI\b", 0), (r"agent", re.I), (r"claude", re.I), (r"codex", re.I),
    (r"\bLLM", re.I), (r"automat", re.I), (r"generated by", re.I), (r"process", re.I),
    (r"harness", re.I), (r"evaluator", re.I), (r"\bparent\b", re.I), (r"robob", re.I),
    (r"delegat", re.I), (r"orchestrat", re.I), (r"\bT3\b", 0)]]


def iter_changes(branch):
    """Yield (artifact, change) for every change pointer in artifact_diff order."""
    for art in branch["artifact_diff"]:
        for ch in art["changes"]:
            yield art, ch


def change_line(ch):
    line = "- `%s`" % ch["kind"]
    if "type" in ch:
        line += " `%s`" % ch["type"]
    line += ": `%s`" % ch["pointer"]
    if "fields" in ch:
        line += " (fields: %s)" % ", ".join(ch["fields"])
    return line


def details(branch):
    total = sum(1 for _ in iter_changes(branch))
    out = ["<details>", "<summary>All %d artifact change pointers</summary>" % total, ""]
    for art in branch["artifact_diff"]:
        ident = "yes" if art["byteIdentical"] else "no"
        out.append("**%s** (byte identical: %s, %d changes)"
                   % (art["artifact"], ident, len(art["changes"])))
        out.append("")
        if not art["changes"]:
            out.append("No changes.")
        out.extend(change_line(ch) for ch in art["changes"])
        out.append("")
    out.append("</details>")
    return "\n".join(out)


def summary_lines(branch):
    out = []
    for art in branch["artifact_diff"]:
        ident = "yes" if art["byteIdentical"] else "no"
        out.append("- %s: %d changes; byte identical: %s"
                   % (art["artifact"], len(art["changes"]), ident))
    counts = collections.Counter(ch["kind"] for _, ch in iter_changes(branch))
    out.append("- Kinds: " + ", ".join("%d %s" % (counts[k], k) for k in sorted(counts)) + ".")
    return out


def tests_lines(branch, native):
    b, h = branch["base_tests"], branch["head_tests"]
    assert h["total"] - b["total"] == 7, "expected seven new tests"
    out = [
        "- Base: %d total, %d pass, %d fail." % (b["total"], b["pass"], b["fail"]),
        "- Head: %d total, %d pass, %d fail." % (h["total"], h["pass"], h["fail"]),
        "- Seven new top-level tests run through the real generator: primitive matrix, "
        "embedded and real JSON Schema controls, heading matrix, response boundary matrix, "
        "real quote, and real metadata.",
        "- Quint was skipped: this change is stateless parsing with no state machine or "
        "concurrency.",
    ]
    if native:
        assert h["fail"] == 0, "native-v1 head has failures"
        out.append("- No failing tests at head.")
    else:
        assert h["fail"] == len(KNOWN), "known failure count drift"
        out.append("- A main fill fee-position cash test had pinned the old defect. "
                   "It now expects an integer or null.")
        out.append("- Known failures at head:")
        out.extend("  - " + item for item in KNOWN)
    return out


def fix_lines(native):
    if native:
        tail = "Native-v1 had neither correction, so this change adds both."
    else:
        tail = ("Main already corrected the list response, so this change corrects "
                "the detail response.")
    return [
        "- Trimmed integer, number, and boolean sample tokens now produce primitive schemas, "
        "including through nullable recursion. Why: the affected fields did not carry the "
        "primitive type before this change.",
        "- Annotated request body headings accept nested parentheses and Markdown links. "
        "Empty, none, type-reference, JSON, and response boundary semantics are unchanged. "
        "Why: those heading forms were not accepted before.",
        "- Edge missing-asset metadata objects (base_asset_metadata, quote_asset_metadata) "
        "allow null on list and detail responses and keep their populated schemas. Why: "
        "metadata for a missing asset can be null, so the schema has to allow it. " + tail,
        "- JSON Schema literal guard: primitive names under a document that declares a JSON "
        "Schema `$schema` stay literal strings. This prevents new collateral changes to "
        "saved-query `params_schema_json`.",
    ]


def pr_body(branch, native):
    lines = ["## Summary", ""]
    if native:
        lines.append("Applies the same generator fixes to the native-v1 line. " + SCOPE)
        lines += ["", "Related: main is #300.", ""]
    else:
        lines.append("Corrects primitive types and nullable asset metadata in the generated "
                     "OpenAPI artifacts for backoffice-core and edge-api. " + SCOPE)
        lines += ["", "Related: the native-v1 line is #301.", ""]
    lines += ["## Fix and why", ""] + fix_lines(native) + [""]
    lines += ["## Tests", ""] + tests_lines(branch, native) + [""]
    lines += ["## Commands", "", "- npm run test:openapi (website/)",
              "- npm run openapi (website/)", ""]
    lines += CI_LINES + [""]
    lines += ["## Artifact evidence", "",
              "Artifact pointers below compare base and head generated outputs.", ""]
    lines += summary_lines(branch) + [""]
    lines.append(details(branch))
    return "\n".join(lines) + "\n"


def handoff():
    mb, mh = MAIN["base_tests"], MAIN["head_tests"]
    nb, nh = NATIVE["base_tests"], NATIVE["head_tests"]
    mcount = sum(1 for _ in iter_changes(MAIN))
    ncount = sum(1 for _ in iter_changes(NATIVE))
    out = [
        "# Card 3409 handoff",
        "",
        "Draft PRs, both mergeable, no checks reported:",
        "- main #300: " + MAIN_PR,
        "- native-v1 #301: " + NATIVE_PR,
        "",
        "## Changes",
        "- Primitive schemas for trimmed integer, number, and boolean sample tokens, "
        "including nullable recursion.",
        "- Request body heading parsing accepts nested parentheses and Markdown links.",
        "- Missing-asset metadata allows null: main on the detail response, native-v1 on "
        "list and detail.",
        "- JSON Schema literal guard: primitive names under a $schema document stay literal "
        "strings, which prevents new collateral changes to saved-query params_schema_json.",
        "",
        "## Test evidence",
        "- main: base %d of %d pass, head %d of %d pass; %d known head failures, listed in "
        "the PR body." % (mb["pass"], mb["total"], mh["pass"], mh["total"], len(KNOWN)),
        "- native-v1: base %d of %d pass, head %d of %d pass."
        % (nb["pass"], nb["total"], nh["pass"], nh["total"]),
        "- npm run test:openapi (website/) and npm run openapi (website/) were run for both "
        "branches.",
        "- Artifact change pointers: main %d, native-v1 %d; all are listed in the PR bodies."
        % (mcount, ncount),
        "",
        "## Notes",
        "- Quint skipped: stateless parsing, no state machine or concurrency.",
        "- No PR CI exists. The deploy workflow (workflow_dispatch only) was not triggered. "
        "See ci-question.txt.",
        "- After merge: publish the next architecture corpus release and arrange the consumer "
        "type resync.",
        "- No live config, infrastructure, or watcher changes are needed.",
    ]
    return "\n".join(out) + "\n"


def ci_question():
    mb, mh = MAIN["base_tests"], MAIN["head_tests"]
    nb, nh = NATIVE["base_tests"], NATIVE["head_tests"]
    out = [
        "Card #3409: accept recorded evidence instead of hosted PR CI?",
        "",
        "Your card #3409 packet (9 Nov 2026, 18:05 Asia/Dubai) says: "
        "'PR(s) open with green CI'.",
        "",
        "There is no PR CI to turn green. The repository tracks no PR CI workflow; its only "
        "workflow is deploy.yml, which runs on workflow_dispatch only. Both draft PRs show no "
        "checks: main #300 and native-v1 #301. No workflows were run, dispatched, or re-run, "
        "and no deploy was triggered.",
        "",
        "Recorded evidence instead:",
        "- Tests: main base %d/%d pass, head %d/%d pass (%d known failures at head); "
        "native-v1 base %d/%d pass, head %d/%d pass."
        % (mb["pass"], mb["total"], mh["pass"], mh["total"], len(KNOWN),
           nb["pass"], nb["total"], nh["pass"], nh["total"]),
        "- npm run test:openapi (website/) and npm run openapi (website/) for both branches.",
        "- Per-pointer artifact diffs, listed in each PR body.",
        "",
        "Reply with one:",
        "- Approve: accept this recorded test and artifact evidence in place of hosted PR CI.",
        "- Change: keep the PRs but require different evidence or a different gate. Say which.",
        "- Drop: do not merge these PRs.",
        "",
        "Card: " + CARD_LINK,
    ]
    return "\n".join(out) + "\n"


def gate(name, text):
    problems = []
    for rx in BANNED:
        if rx.search(text):
            problems.append("banned word: " + rx.pattern)
    if name != "ci-question.txt":
        for rx in MARKERS:
            if rx.search(text):
                problems.append("marker: " + rx.pattern)
    if name.endswith("title.txt"):
        title = text.rstrip("\n")
        if "\n" in title or len(title) > 72 or not TITLE_RE.match(title):
            problems.append("title is not Conventional Commits or exceeds 72 chars")
    if name.endswith("body.md"):
        branch = MAIN if name.startswith("pr-main") else NATIVE
        needles = [
            "npm run test:openapi (website/)", "npm run openapi (website/)",
            "JSON Schema literal guard", "<details>", "</details>", "No PR CI exists",
            "not triggered", "Base: %d total" % branch["base_tests"]["total"],
            "Head: %d total" % branch["head_tests"]["total"],
        ]
        problems += ["missing: " + n for n in needles if n not in text]
        rows = [l for l in text.splitlines() if l.startswith("- `") and ": `/" in l]
        expected = sum(1 for _ in iter_changes(branch))
        if len(rows) != expected:
            problems.append("pointer rows %d, expected %d" % (len(rows), expected))
        problems += ["pointer missing: " + ch["pointer"] for _, ch in iter_changes(branch)
                     if "`%s`" % ch["pointer"] not in text]
    if name == "handoff.md":
        problems += ["missing: " + n for n in ("Quint", "stateless", "corpus", "resync",
                                                "ci-question.txt") if n not in text]
    if name == "ci-question.txt":
        problems += ["missing: " + n for n in ("Approve", "Change", "Drop", CARD_LINK,
                                                "'PR(s) open with green CI'", "9 Nov 2026",
                                                "18:05 Asia/Dubai") if n not in text]
    return problems


def main():
    texts = {
        "pr-main-title.txt": MAIN_TITLE + "\n",
        "pr-main-body.md": pr_body(MAIN, False),
        "pr-native-title.txt": NATIVE_TITLE + "\n",
        "pr-native-body.md": pr_body(NATIVE, True),
        "handoff.md": handoff(),
        "ci-question.txt": ci_question(),
    }
    for name, text in texts.items():
        with open(os.path.join(OUT, name), "w", encoding="ascii", newline="\n") as fh:
            fh.write(text)
    failed = False
    for name in texts:
        path = os.path.join(OUT, name)
        with open(path, encoding="ascii") as fh:
            problems = gate(name, fh.read())
        failed = failed or bool(problems)
        print("%-20s %6d bytes  %s" % (name, os.path.getsize(path),
                                       "ok" if not problems else "; ".join(problems)))
    print("pointers: main=%d native-v1=%d" % (sum(1 for _ in iter_changes(MAIN)),
                                             sum(1 for _ in iter_changes(NATIVE))))
    sys.exit(1 if failed else 0)


if __name__ == "__main__":
    main()
PYEOF
python3 -I "$SCRIPT_DIR/write_card.py" "/Users/ardud/checkouts/broker-openapi-primitives/tmp/card-3409"
